+            )
+        );
+        assertThat(request2.validate().getMessage(), containsString("[labels] hint key cannot contain wildcard"));
+
+        final SuggestProfilesRequest request3 = new SuggestProfilesRequest(
+            randomDataKeys(),
+            randomName(),
+            randomSize(),
